//! 🪆️ A checkpoint cascade retains one original authored metadata source and returns that exact parent authority after every child alias closes.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSourceTake;
/// 🗂️ The actual fixed registry backing, admission generation and live count fence its dense member order.
pub type ChildRosterIdentity=(usize,u64,usize);
/// 📌️ Pins reserve their real canonical backing once; each child copies only the metadata it actually commits.
pub struct ChildCheckpointCascade{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,roster:ChildRosterIdentity,metadata:ManuallyDrop<Option<CheckpointMetadata>>,source:ManuallyDrop<Option<RetainedCloneSource<CheckpointMetadata>>>,child:ManuallyDrop<Option<Box<ChildCheckpointUnit>>>,pins:ManuallyDrop<Option<Vec<CompositionPin>>>,pin:ManuallyDrop<Option<(bool,Option<CompositionPin>)>>,retirement:RetainedCloneClose,next:usize,changed:bool,phase:u8,closing:bool}
impl ChildCheckpointCascade{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<(Self,Option<CheckpointMetadata>)>()}}
 pub fn admit(metadata:&mut Option<CheckpointMetadata>,roster:ChildRosterIdentity,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if metadata.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::capture_demands();admit_original_construction(cx,output,original(d),|control|Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,roster,metadata:ManuallyDrop::new(metadata.take()),source:ManuallyDrop::new(None),child:ManuallyDrop::new(None),pins:ManuallyDrop::new(None),pin:ManuallyDrop::new(None),retirement:Default::default(),next:0,changed:false,phase:0,closing:false}),paid(d))))}
 fn validate(&self,roster:ChildRosterIdentity,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder)||self.roster!=roster{return Err(invalid().into())}Ok(())}
 pub fn next_construction_demands<M:SpaceMember>(&self,member:Option<&M>)->Option<RetirementDemand>{if self.phase==2&&self.next!=self.roster.2{Some(ChildCheckpointUnit::capture_demands())}else{self.child.as_ref().and_then(|c|member.and_then(|m|c.next_construction_demands(m)))}}
 pub fn next(&self)->usize{self.next}
 pub fn roster(&self)->ChildRosterIdentity{self.roster}
 pub fn ready(&self)->bool{self.phase==8&&!self.closing}
 fn action(&mut self,cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut Self)->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{run(self)?;Ok(((),paid(d)))})?;Ok(done.is_some())}
 pub fn advance<M:SpaceMember>(&mut self,roster:ChildRosterIdentity,mut member:Option<&mut M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if self.closing||cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original child checkpoint cascade was cancelled").into())}match self.phase{
 0=>{let birth=RetainedCloneSource::<CheckpointMetadata>::owned_constructor_demand::<()>();let d=RetirementDemand{capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()};let g=cx.retained_grant();if admit_original_construction(cx,&mut self.source,original(d),|_|RetainedCloneSource::admit_owned(self.metadata.take().ok_or_else(invalid)?,(),g).map_err(|(e,value,())|{*self.metadata=Some(value);e}))?{self.phase=1;}},
 1=>{let d=RetirementDemand{capacity_bytes:self.roster.2.checked_mul(size_of::<CompositionPin>()).ok_or_else(invalid)?,..header::<Vec<CompositionPin>>()};if admit_original_construction(cx,&mut self.pins,original(d),|_|{let mut pins=Vec::new();pins.try_reserve_exact(self.roster.2).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original child checkpoint pin rows could not be reserved"))?;Ok((pins,paid(d)))})?{self.phase=2;}},
 2=>{if self.next==self.roster.2{self.action(cx,header::<u8>(),|s|{s.phase=7;Ok(())})?;}else if ChildCheckpointUnit::admit(cx,&mut self.child)?{self.phase=3;}},
 3=>{if self.child.as_mut().unwrap().advance(member.as_deref_mut().ok_or_else(invalid)?,self.source.as_ref().unwrap(),cx)?{self.phase=4;}},
 4=>{if self.child.as_mut().unwrap().take_pin(cx,&mut self.pin)?{self.phase=5;}},
 5=>{if self.close_child(member.as_deref_mut(),cx)?{self.action(cx,header::<u8>(),|s|{s.phase=6;Ok(())})?;}},
 6=>{self.action(cx,header::<(Option<(bool,Option<CompositionPin>)>,CompositionPin,usize,bool,u8)>(),|s|{let(changed,pin)=s.pin.take().ok_or_else(invalid)?;s.changed|=changed;if let Some(pin)=pin{let pins=s.pins.as_mut().unwrap();if pins.len()==pins.capacity(){return Err(invalid())}pins.push(pin);}s.next+=1;s.phase=2;Ok(())})?;},
 7=>{let d=self.source.as_ref().unwrap().next_take_demand(self.body)?;let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{let p=match self.source.as_mut().unwrap().take_authority(g)?{RetainedCloneSourceTake::Pending(p)=>p,RetainedCloneSourceTake::Ready(metadata,p)=>{*self.metadata=Some(metadata);self.source.take();self.phase=8;p}};Ok(((),p))})?;},8=>{},_=>return Err(invalid().into()),}Ok(self.ready())}
 pub fn take(&mut self,roster:ChildRosterIdentity,cx:&mut StepContext<'_>,output:&mut Option<(CheckpointMetadata,Vec<CompositionPin>,bool)>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if !self.ready(){return Err(invalid().into())}let d=header::<(CheckpointMetadata,Vec<CompositionPin>,bool,u8)>();admit_original_construction(cx,output,original(d),|_|{self.phase=9;Ok(((self.metadata.take().ok_or_else(invalid)?,self.pins.take().ok_or_else(invalid)?,self.changed),paid(d)))})}
 fn close_child<M:SpaceMember>(&mut self,member:Option<&mut M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(child)=self.child.as_mut()else{return Ok(true)};if !child.terminal_is_empty(){cx.with_original_retirement(|cx|child.close_step(member.ok_or_else(invalid)?,cx))?;return Ok(false)}let mut d=ChildCheckpointUnit::release_demands();d.copy_bytes=size_of::<Option<Box<ChildCheckpointUnit>>>();close_original_retained_step(cx,d,|_|{self.child.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;Ok(false)}
 pub fn close_demands<M:SpaceMember>(&self,member:Option<&M>)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if let Some(child)=self.child.as_ref(){return if child.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<ChildCheckpointUnit>>>(),..ChildCheckpointUnit::release_demands()})}else{child.close_demands(member.ok_or_else(invalid)?)}}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(header::<Option<RetainedCloneSource<CheckpointMetadata>>>())}else{source.next_close_demand(self.body)}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<CheckpointMetadata>(true,&None,self.body)}if self.pins.is_some(){return self.retirement.next_owner_demands::<Vec<CompositionPin>>(true,&None,self.body)}if self.pin.is_some(){return self.retirement.next_owner_demands::<(bool,Option<CompositionPin>)>(true,&None,self.body)}Ok(Default::default())}
 pub fn close_step<M:SpaceMember>(&mut self,roster:ChildRosterIdentity,member:Option<&mut M>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(roster,cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands(member.as_deref())?;if !self.closing{close_original_retained_step(cx,d,|_|{self.closing=true;Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(false)}if !self.close_child(member,cx)?{return Ok(false)}if self.source.is_some(){close_original_retained_step(cx,d,|g|{if !self.source.as_ref().unwrap().terminal_is_empty(){return self.source.as_mut().unwrap().close_step(g)}self.source.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(false)}close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}if self.metadata.is_some(){return Ok(self.retirement.begin_granted(&mut self.metadata,g)?.ok_or_else(invalid)?)}if self.pins.is_some(){return Ok(self.retirement.begin_granted(&mut self.pins,g)?.ok_or_else(invalid)?)}if self.pin.is_some(){return Ok(self.retirement.begin_granted(&mut self.pin,g)?.ok_or_else(invalid)?)}Ok(RetainedCloneStep::Complete(Default::default()))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.metadata.is_none()&&self.source.is_none()&&self.child.is_none()&&self.pins.is_none()&&self.pin.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for ChildCheckpointCascade{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original child checkpoint cascade requires funded closure")}}
